#!/usr/bin/env python3

import argparse
import subprocess
import os
import pathlib
import shutil

# go mod vendor only copies directories of imported packages, so every
# header directory is a package that imports its subdirectories, and the
# root package imports the top directories. See tommie/v8go#116.
vendor_file_template = """// Generated by deps/build_common.py. DO NOT EDIT.

// Package %s holds C++ header files. It exists so go mod vendor copies them.
package %s
%s"""

deps_path = os.path.dirname(os.path.realpath(__file__))
v8go_path = os.path.abspath(os.path.join(deps_path, os.pardir))
env = os.environ.copy()
v8_path = os.path.join(deps_path, "v8")
v8_include_path = os.path.join(v8_path, "include")
deps_include_path = os.path.join(deps_path, "include")

# The cgo bridge must be compiled with the libc++ that V8 was built
# with, since V8's API uses std:: types. These are gclient
# dependencies, not part of the V8 repository.
libcxx_headers = [
  (os.path.join(v8_path, "third_party", "libc++", "src", "include"),
   os.path.join(deps_path, "include_libcxx")),
  (os.path.join(v8_path, "third_party", "libc++abi", "src", "include"),
   os.path.join(deps_path, "include_libcxxabi")),
]
# Chromium's configuration of libc++, e.g. the std::__Cr ABI namespace.
libcxx_config_path = os.path.join(v8_path, "buildtools", "third_party", "libc++")

gclient_sln = [
  { "name"        : "v8",
    "url"         : "https://chromium.googlesource.com/v8/v8.git",
    "deps_file"   : "DEPS",
    "managed"     : False,
    "custom_deps" : {
      "v8/testing/gmock"                : None,
      "v8/test/wasm-js"                 : None,
      "v8/third_party/colorama/src"     : None,
      "v8/tools/gyp"                    : None,
      "v8/tools/luci-go"                : None,
      "v8/third_party/catapult"         : None,
      "v8/third_party/android_tools"    : None,
    },
    "custom_vars": {
      "build_for_node" : True,
    },
  },
]

def v8deps():
  spec = "solutions = %s\n" % gclient_sln
  sync_env = env.copy()
  sync_env["PATH"] = os.path.join(deps_path, "depot_tools") + os.pathsep + sync_env["PATH"]
  subprocess.check_call(["gclient", "sync", "--no-history", "--spec", spec],
                        cwd=deps_path,
                        env=sync_env)

def copy_libcxx_headers():
  for src, dest in libcxx_headers:
    if os.path.exists(dest):
      shutil.rmtree(dest)
    shutil.copytree(src, dest)

  for name in ("__config_site", "__assertion_handler"):
    shutil.copy2(os.path.join(libcxx_config_path, name), libcxx_headers[0][1])

# The header directories copied into deps/, relative to the v8go root.
vendored_include_paths = ["deps/include", "deps/include_libcxx", "deps/include_libcxxabi"]

def get_module_name():
  gomod = subprocess.check_output(["go", "mod", "edit", "-print"], cwd=deps_path, env=env).decode('utf-8')
  return [line.split(" ")[1].strip() for line in gomod.strip().splitlines() if line.startswith("module ")][0]

def create_vendor_files(src_path, import_path):
  """Writes vendor.go in src_path and all its subdirectories."""
  directories = sorted(p.name for p in pathlib.Path(src_path).iterdir() if p.is_dir())
  name = os.path.basename(src_path)
  if not name.isidentifier():
    raise ValueError(f"directory name is not a valid Go package name: {src_path}")

  imports = ""
  if directories:
    imports = "\nimport (\n" + "".join(f'\t_ "{import_path}/{d}"\n' for d in directories) + ")\n"

  with open(os.path.join(src_path, "vendor.go"), "w") as f:
    f.write(vendor_file_template % (name, name, imports))

  for directory in directories:
    create_vendor_files(os.path.join(src_path, directory), import_path + "/" + directory)

def create_all_vendor_files(module):
  for path in vendored_include_paths:
    create_vendor_files(os.path.join(v8go_path, path), module + "/" + path)

if __name__ == "__main__":
  argp = argparse.ArgumentParser()
  argp.add_argument("--vendor-files-only", action="store_true",
                    help="only regenerate vendor.go files in the existing header directories")
  args = argp.parse_args()

  module = get_module_name()
  if not args.vendor_files_only:
    v8deps()
    shutil.rmtree(deps_include_path)
    shutil.copytree(v8_include_path, deps_include_path, dirs_exist_ok=True)
    copy_libcxx_headers()
  create_all_vendor_files(module)
